const fs = require('fs');
const path = require('path');

const srcDir = path.join(__dirname, 'src');

function walk(dir, callback) {
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const p = path.join(dir, file);
    if (fs.statSync(p).isDirectory()) {
      walk(p, callback);
    } else {
      callback(p);
    }
  }
}

let changedCount = 0;

walk(srcDir, (filepath) => {
  if (!filepath.endsWith('.tsx') && !filepath.endsWith('.ts')) return;

  let content = fs.readFileSync(filepath, 'utf-8');
  let newContent = content;

  // Dark mode background
  newContent = newContent.replace(
    /radial-gradient\(ellipse 80% 60% at 50% 0%, #1e40af 0%, #0f172a 60%, #020617 100%\)/g,
    'radial-gradient(ellipse 80% 60% at 50% 0%, #262626 0%, #171717 60%, #0a0a0a 100%)'
  );

  // Light mode background
  newContent = newContent.replace(
    /radial-gradient\(ellipse 80% 60% at 50% 0%, #bfdbfe 0%, #e0f2fe 40%, #f8fafc 100%\)/g,
    'radial-gradient(ellipse 80% 60% at 50% 0%, #fef3c7 0%, #f5f5f5 40%, #ffffff 100%)'
  );

  // Soft glow - dark
  newContent = newContent.replace(
    /radial-gradient\(ellipse 55% 40% at 50% 15%, rgba\(59,130,246,0.25\) 0%, transparent 70%\)/g,
    'radial-gradient(ellipse 55% 40% at 50% 15%, rgba(212,175,55,0.15) 0%, transparent 70%)'
  );

  newContent = newContent.replace(
    /radial-gradient\(ellipse 55% 40% at 50% 20%, rgba\(59,130,246,0.35\) 0%, transparent 70%\)/g,
    'radial-gradient(ellipse 55% 40% at 50% 20%, rgba(212,175,55,0.15) 0%, transparent 70%)'
  );

  // Soft glow - light
  newContent = newContent.replace(
    /radial-gradient\(ellipse 55% 40% at 50% 15%, rgba\(99,179,237,0.35\) 0%, transparent 70%\)/g,
    'radial-gradient(ellipse 55% 40% at 50% 15%, rgba(223,177,41,0.15) 0%, transparent 70%)'
  );

  // Layout themeColor dark
  newContent = newContent.replace(
    /{ media: "\\(prefers-color-scheme: dark\\)", color: "#060b1a" }/g,
    '{ media: "(prefers-color-scheme: dark)", color: "#0a0a0a" }'
  );

  // Bottom fade dark
  newContent = newContent.replace(
    /rgba\(2,6,23,0\.85\)/g,
    'rgba(10,10,10,0.85)'
  );

  // Bottom fade light
  newContent = newContent.replace(
    /rgba\(240,249,255,0\.85\)/g,
    'rgba(255,255,255,0.85)'
  );

  // Flare beams
  if (filepath.includes('BackgroundFlare.tsx')) {
    newContent = newContent.replace(
      /from-blue-400\/20 via-cyan-400\/5 dark:from-blue-500\/30 dark:via-cyan-400\/10/g,
      'from-gold-400/20 via-gold-300/5 dark:from-gold-500/30 dark:via-gold-400/10'
    );
    newContent = newContent.replace(
      /from-indigo-400\/20 via-violet-400\/5 dark:from-indigo-500\/30 dark:via-violet-400\/10/g,
      'from-amber-400/20 via-orange-400/5 dark:from-amber-500/30 dark:via-amber-400/10'
    );
    newContent = newContent.replace(
      /from-blue-500\/10 dark:from-blue-900\/40/g,
      'from-gold-600/10 dark:from-gold-700/30'
    );
  }

  if (content !== newContent) {
    fs.writeFileSync(filepath, newContent, 'utf-8');
    console.log(`Updated ${filepath}`);
    changedCount++;
  }
});

console.log(`Done! Replaced gradient themes in ${changedCount} files.`);

const fs = require("fs");

function replaceThemeClass(dir) {
  const list = fs.readdirSync(dir);
  list.forEach(file => {
    file = dir + "/" + file;
    const stat = fs.statSync(file);
    if (stat && stat.isDirectory()) {
      replaceThemeClass(file);
    } else if (file.endsWith(".tsx") || file.endsWith(".ts") || file.endsWith(".css")) {
      const originalContent = fs.readFileSync(file, "utf8");
      // globally replacing navy with neutral
      const newContent = originalContent.replace(/navy-/g, "neutral-");
      if (originalContent !== newContent) {
        fs.writeFileSync(file, newContent, "utf8");
        console.log(`Updated theme in ${file}`);
      }
    }
  });
}

replaceThemeClass("src");

import fs from 'fs';

const content = fs.readFileSync('src/lib/i18n.ts', 'utf8');

// Find where "th: {" starts
const thStart = content.indexOf('  th: {');
// Find where "en: {" starts, which is after th object ends
const enStart = content.indexOf('  en: {');

// The end of `th` is right before `en: {` (ignoring whitespace/comma)
const thContent = content.substring(thStart + 6, enStart - 3).trim();

// The end of `en` is right before `} as const;` or `};` block ends
const _enEnd = content.lastIndexOf('    },');
const enContentRaw = content.substring(enStart + 6);
const justEnContent = enContentRaw.substring(0, enContentRaw.lastIndexOf('    }') + 6);

const thFile = `export default ${thContent};`;
const enFile = `export default ${justEnContent};`;

fs.writeFileSync('src/lib/dictionaries/th.ts', thFile);
fs.writeFileSync('src/lib/dictionaries/en.ts', enFile);

// rewrite i18n
const newI18n = `import type th from "./dictionaries/th";

export type Language = "th" | "en";
export type Dictionary = typeof th;

const dictionaries = {
  th: () => import('./dictionaries/th').then((module) => module.default),
  en: () => import('./dictionaries/en').then((module) => module.default),
};

export const getDictionary = async (locale: Language) => {
  if (!dictionaries[locale]) {
    console.warn(\`Dictionary not found for \${locale}, falling back to th\`);
    return dictionaries.th();
  }
  return dictionaries[locale]();
};

// For backward compatibility during migration, we can load a default dictionary synchronously
// but this defeats lazy loading for initial renders if used globally.
import defaultDictionary from "./dictionaries/th";
export const defaultDict = defaultDictionary;
`;
fs.writeFileSync('src/lib/i18n.ts', newI18n);

console.log("Done splitting");

import { describe, expect, it, vi, beforeEach } from 'vitest';

vi.mock('@/lib/services/newsService', () => ({
  newsService: { trackAnalytics: vi.fn() },
}));

import { POST } from '@/app/api/articles/[slug]/track/route';
import { newsService } from '@/lib/services/newsService';

describe('POST /api/articles/[slug]/track', () => {
  beforeEach(() => { vi.clearAllMocks(); });

  it('tracks an article successfully', async () => {
    (newsService.trackAnalytics as any).mockResolvedValue(true);

    const req = new Request('http://localhost/api/articles/test-article/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ views: 1, activeSeconds: 10, bounceRate: 0.5 }),
    });

    const res = await POST(req as any, { params: Promise.resolve({ slug: 'test-article' }) });
    const data = await res.json();

    expect(data.success).toBe(true);
    expect(newsService.trackAnalytics).toHaveBeenCalledWith('test-article', { views: 1, activeSeconds: 10, bounceRate: 0.5 });
  });

  it('handles invalid payload', async () => {
    const req = new Request('http://localhost/api/articles/test-article/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ views: "not a number" }),
    });

    const res = await POST(req as any, { params: Promise.resolve({ slug: 'test-article' }) });
    const data = await res.json();

    expect(res.status).toBe(400);
    expect(data.error).toBe('Invalid tracking payload');
  });

  it('handles server error', async () => {
    (newsService.trackAnalytics as any).mockRejectedValue(new Error('DB Error'));

    const req = new Request('http://localhost/api/articles/test-article/track', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ views: 1 }),
    });

    const res = await POST(req as any, { params: Promise.resolve({ slug: 'test-article' }) });
    expect(res.status).toBe(500);
  });
});

