export default async function Home() {
  const countries = await getActiveCountries();
  const dbBanners = await getActiveBanners();

  // Deduplicate by country code
  const seen = new Set<string>();
  const tabs = [
    { id: "all", label: "all", flag: null },
    ...countries
      .filter((c) => {
        const key = c.code.toLowerCase();
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .map((c) => ({
        id: c.code.toLowerCase(),
        label: c.code.toLowerCase(),
        flag: getFlagUrl(c.code.toLowerCase()),
      })),
  ];

  const seenCountry = new Set<string>();
  const countryListItems = countries
    .filter((c) => {
      const key = c.code.toLowerCase();
      if (seenCountry.has(key)) return false;
      seenCountry.add(key);
      return true;
    })
    .map((c) => ({
      id: c.code.toLowerCase(),
      name: c.name,
      count: c.lotteries.length,
      flag: c.code.toLowerCase(),
    }));

  // Build lottery groups for CheckLotteryWidget dropdown
  const groupSeen = new Set<string>();
  const lotteryGroups: LotteryGroup[] = countries
    .filter((c) => {
      const key = c.code.toLowerCase();
      if (groupSeen.has(key)) return false;
      groupSeen.add(key);
      return true;
    })
    .map((c) => ({
      countryCode: c.code.toLowerCase(),
      countryName: c.name,
      lotteries: c.lotteries
        .filter((l) => l.is_active)
        .map((l) => ({
          id: `${c.code.toLowerCase()}-${l.id}`,
          name: l.name,
          countryCode: c.code.toLowerCase(),
          countryName: c.name,
          logo: l.logo ?? null,
        })),
    }))
    .filter((g) => g.lotteries.length > 0);

  const heroItems: HeroItem[] = [];

  // 1. Create banners from DB
  for (const banner of dbBanners) {
    const lotto = banner.lottery_results?.lottery;
    const country = lotto?.countries;
    if (!lotto || !country) continue;

    const code = country.code.toLowerCase();
    const theme = GRADIENTS[code] || DEFAULT_GRADIENT;
    const jackpotInfo = JACKPOT_DATA[code];
    const jackpot = jackpotInfo?.main || DEFAULT_JACKPOT;
    const lottoSlug = slugify(lotto.name);
    const nextDraw = country.draw_schedule || "Next Draw Soon";

    // Compute a fallback nextDrawDate (14 days from now if no schedule)
    const drawDate = new Date();
    drawDate.setDate(drawDate.getDate() + 14);
    const nextDrawDate = drawDate.toISOString();

    heroItems.push({
      id: `banner-${banner.id}`,
      name: lotto.name,
      country: country.name,
      flag: getFlagUrl(code),
      jackpot,
      nextDraw,
      gradientFrom: theme.from,
      gradientTo: theme.to,
      href: `/${code}/${lottoSlug}`,
      bgImage: banner.image_url || theme.bg,
      prizes: jackpotInfo?.prizes,
      nextDrawDate,
    });
  }

  // 2. Fallback — create banners from countries
  if (heroItems.length === 0) {
    for (const country of countries) {
      const code = country.code.toLowerCase();
      for (const lotto of country.lotteries) {
        if (!lotto.is_active) continue;

        const theme = GRADIENTS[code] || DEFAULT_GRADIENT;
        const jackpotInfo = JACKPOT_DATA[code];
        const jackpot = jackpotInfo?.main || DEFAULT_JACKPOT;
        const lottoSlug = slugify(lotto.name);
        const nextDraw = country.draw_schedule || "Next Draw Soon";

        const drawDate = new Date();
        drawDate.setDate(drawDate.getDate() + 14);
        const nextDrawDate = drawDate.toISOString();

        heroItems.push({
          id: `${code}-${lotto.id}`,
          name: lotto.name,
          country: country.name,
          flag: getFlagUrl(code),
          jackpot,
          nextDraw,
          gradientFrom: theme.from,
          gradientTo: theme.to,
          href: `/${code}/${lottoSlug}`,
          bgImage: theme.bg,
          prizes: jackpotInfo?.prizes,
          nextDrawDate,
        });

        break;
      }
    }
  }

  return (
    <div className="flex flex-col relative">
      <JsonLd />
      {/* Background — dark mode: deep navy radial, light mode: soft sky-to-white radial */}
      {/* Dark mode background */}
      <div
        className="pointer-events-none fixed inset-0 -z-10 hidden dark:block"
        style={{
          background:
            "radial-gradient(ellipse 80% 60% at 50% 0%, #262626 0%, #171717 60%, #0a0a0a 100%)",
        }}
      />
      {/* Light mode background */}
      <div
        className="pointer-events-none fixed inset-0 -z-10 block dark:hidden"
        style={{
          background:
            "radial-gradient(ellipse 80% 60% at 50% 0%, #fef3c7 0%, #f5f5f5 40%, #ffffff 100%)",
        }}
      />
      {/* Soft blue glow layer — adapts per theme */}
      <div
        className="pointer-events-none fixed inset-0 -z-10 hidden dark:block"
        style={{
          background:
            "radial-gradient(ellipse 55% 40% at 50% 15%, rgba(212,175,55,0.15) 0%, transparent 70%)",
        }}
      />
      <div
        className="pointer-events-none fixed inset-0 -z-10 block dark:hidden"
        style={{
          background:
            "radial-gradient(ellipse 55% 40% at 50% 15%, rgba(223,177,41,0.15) 0%, transparent 70%)",
        }}
      />


      {/* Section 1: Hero Carousel */}
      <HeroSectionV2 items={heroItems} />

      {/* Section 2: Lottery By Country Marquee */}
      <CountryMarqueeSection countries={countryListItems} />

      {/* Section 3: Live Ticker */}
      {/* <LiveTicker /> */}

      {/* Section 4: Find By Number
      <CheckLotteryWidget lotteryGroups={lotteryGroups} /> */}

      <GlobalStatsBanner 
        countriesCount={countryListItems.length}
        lotteriesCount={lotteryGroups.reduce((acc, curr) => acc + curr.lotteries.length, 0)}
      />

      <LatestUpdateSection />

    </div>
  );
}

