"use client";

import { useState, useCallback, useEffect } from "react";
import { useLanguage } from "@/contexts/LanguageContext";
import { PinnedLotteryTabs } from "./PinnedLotteryTabs";
import { ResultBoardCard } from "./ResultBoardCard";
import { AddLotteryModal } from "./AddLotteryModal";
import type { PinnedLottery } from "./AddLotteryModal";

const STORAGE_KEY = "lottox_pinned_lotteries";
const MAX_PINNED = 6;

/** Read pinned lotteries from localStorage, auto-migrating old format */
function readPinned(): PinnedLottery[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as Record<string, unknown>[];
    // Migration: old format had { countryCode, lotteryName } without lotteryId
    if (parsed.length > 0 && !("lotteryId" in parsed[0])) {
      localStorage.removeItem(STORAGE_KEY);
      return [];
    }
    return parsed as unknown as PinnedLottery[];
  } catch {
    return [];
  }
}

function writePinned(pinned: PinnedLottery[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(pinned));
  } catch { /* ignore */ }
}

export function MyResultBoard() {
  const { t } = useLanguage();
  const mb = t.staticParams.myBoard;

  // Use lazy initializer to load from localStorage immediately on client.
  // The `hydrated` flag prevents flash of empty state during SSR/hydration.
  const [hydrated, setHydrated] = useState(false);
  const [pinned, setPinned] = useState<PinnedLottery[]>([]);
  const [activeIndex, setActiveIndex] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);

  // Load pinned lotteries from localStorage after hydration
  useEffect(() => {
    setPinned(readPinned());
    setHydrated(true);
  }, []);

  /** Handle batch confirm from AddLotteryModal */
  const handleConfirm = useCallback(
    (selected: PinnedLottery[]) => {
      const next = selected.slice(0, MAX_PINNED);
      setPinned(next);
      writePinned(next);
      // Keep active index in bounds
      setActiveIndex((prev) =>
        next.length === 0 ? 0 : Math.min(prev, next.length - 1)
      );
      setModalOpen(false);
    },
    [],
  );

  const handleRemove = useCallback(
    (lotteryId: number) => {
      const next = pinned.filter((p) => p.lotteryId !== lotteryId);
      setPinned(next);
      writePinned(next);
      setActiveIndex((prev) => Math.min(prev, Math.max(0, next.length - 1)));
    },
    [pinned],
  );

  const canAdd = pinned.length < MAX_PINNED;
  const activePinned = pinned[activeIndex] ?? null;

  return (
    <section data-testid="my-result-board">
      {/* Section Header */}
      <div className="flex items-start justify-between mb-6 gap-4 flex-wrap">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
            {mb.title}
          </h2>
          <p className="text-gray-500 text-sm mt-1">{mb.subtitle}</p>
        </div>

        {canAdd && (
          <button
            onClick={() => setModalOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-amber-400 hover:bg-amber-300 text-neutral-950 font-bold rounded-xl text-sm transition-colors"
            data-testid="add-lottery-button"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={2.5}
              className="w-4 h-4"
            >
              <path d="M12 5v14M5 12h14" />
            </svg>
            {mb.addLottery}
          </button>
        )}
      </div>

      {/* Tabs */}
      <div className="mb-5">
        <PinnedLotteryTabs
          pinned={pinned}
          activeIndex={activeIndex}
          onSelect={setActiveIndex}
        />
      </div>

      {/* Active Board Card */}
      {activePinned ? (
        <ResultBoardCard
          key={activePinned.lotteryId}
          lotteryName={activePinned.lotteryName}
          countryCode={activePinned.countryCode}
          onRemove={() => handleRemove(activePinned.lotteryId)}
        />
      ) : hydrated ? (
        <div
          className="text-center py-16 text-gray-500"
          data-testid="empty-board-state"
        >
          <div className="text-4xl mb-2">📋</div>
          <p className="text-sm">{mb.noLotteryPinned}</p>
        </div>
      ) : null}

      {/* Modal */}
      {modalOpen && (
        <AddLotteryModal
          pinned={pinned}
          onConfirm={handleConfirm}
          onClose={() => setModalOpen(false)}
        />
      )}
    </section>
  );
}

"use client";

import { useState, useRef, useEffect, useMemo } from "react";
import Image from "next/image";
import { useLanguage } from "@/contexts/LanguageContext";
import { Search, Loader2, CheckCircle2, XCircle, ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { getFlagUrl } from "@/lib/flags";
import { type Language } from "@/lib/i18n";
import { JackpotResult, StandardWinResult, NoWinResult } from "./ResultStates";
import { getRule, type LotteryNumberRule } from "@/lib/utils/lotteryValidation";

/* ---------- Types ---------- */
export interface LotteryOption {
  id: string;
  name: string;
  countryCode: string;
  countryName: string;
  logo?: string | null;
}


export interface LotteryGroup {
  countryCode: string;
  countryName: string;
  lotteries: LotteryOption[];
}

export interface CheckResult {
  isWinner?: boolean;
  win?: boolean;
  prizes?: Array<{
    prizeName?: string;
    category?: string;
    label?: string;
    number?: string;
    winningNumber?: string;
    amount?: number | string;
  }>;
}

/* ---------- Component ---------- */
export function CheckLotteryWidget({
  lotteryGroups = [],
}: {
  lotteryGroups?: LotteryGroup[];
}) {
  const { t } = useLanguage();
  const [number, setNumber] = useState("");
  const [searchedNumber, setSearchedNumber] = useState(""); // frozen at search time
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<CheckResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [isOpen, setIsOpen] = useState(false);
  const [selected, setSelected] = useState<LotteryOption | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const dropdownRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  // Default selection: first lottery in the list
  useEffect(() => {
    if (!selected && lotteryGroups.length > 0 && lotteryGroups[0].lotteries.length > 0) {
      setSelected(lotteryGroups[0].lotteries[0]);
    }
  }, [lotteryGroups, selected]);

  // Click-outside to close dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const target = event.target as Node;
      if (
        dropdownRef.current && !dropdownRef.current.contains(target) &&
        panelRef.current && !panelRef.current.contains(target)
      ) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
    }
  }, [isOpen]);

  const handleSelect = (lottery: LotteryOption) => {
    setSelected(lottery);
    setIsOpen(false);
    setSearchQuery("");
  };

  // Focus search input when dropdown opens
  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [isOpen]);

  // Filter groups by search query
  const filteredGroups = searchQuery.trim()
    ? lotteryGroups
        .map((group) => ({
          ...group,
          lotteries: group.lotteries.filter(
            (l) =>
              l.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
              l.countryName.toLowerCase().includes(searchQuery.toLowerCase())
          ),
        }))
        .filter((g) => g.lotteries.length > 0)
    : lotteryGroups;

  // Compute validation rule based on selected lottery
  const activeRule: LotteryNumberRule = useMemo(() => {
    if (!selected) return getRule("default");
    return getRule(selected.countryCode, selected.name);
  }, [selected]);

  const isNumberValid = number.length >= activeRule.minDigits && number.length <= activeRule.digits;

  const handleCheck = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!number || !isNumberValid || !selected) return;

    setLoading(true);
    setError(null);
    setResult(null);
    setSearchedNumber(number); // freeze the number at search time

    try {
      const apiType = selected.countryCode.toUpperCase();
      const res = await fetch(`/api/check?number=${number}&type=${apiType}`);
      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || "Failed to check lottery");
      }

      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);
    }
  };

  // Truncate name for trigger display
  const triggerLabel = selected
    ? selected.name.length > 8
      ? selected.name.slice(0, 8) + "..."
      : selected.name
    : "Select...";

  // Determine if it's a jackpot win
  // 1. Result must be a win
  // 2. We check if any prize label contains '1st', 'jackpot', 'grande', 'first', 'prize_1'
  const isWinner = result?.isWinner || result?.win;
  const isJackpot = isWinner && result?.prizes?.some(p => {
    const name = (p.prizeName || p.label || p.category || "").toLowerCase();
    return (
      name.includes("1st") ||
      name.includes("first") ||
      name.includes("jackpot") ||
      name.includes("grande") ||
      name.includes("รางวัลที่ 1") ||
      name === "prize_1"
    );
  });

  const handleReset = () => {
    setResult(null);
    setNumber("");
    setSearchedNumber("");
    setError(null);
  };

  return (
    <section className="container mx-auto px-4 py-10">
      {/* Title */}
      <div className="text-center mb-6">
        <h2 className="text-2xl md:text-3xl font-bold text-gray-900 dark:text-white mb-2">
          {t.common.findByNumber}
        </h2>
        <p className="text-sm text-gray-500 dark:text-gray-400 max-w-lg mx-auto">
          {t.common.findByNumberDesc}
        </p>
      </div>

      {/* Compact search form */}
      <div className="max-w-2xl mx-auto relative">
        <form
          onSubmit={handleCheck}
          className="flex flex-wrap md:flex-nowrap items-center gap-2 bg-white/80 dark:bg-neutral-900/60 border border-gray-200 dark:border-white/10 rounded-2xl md:rounded-full p-2 md:p-1.5 md:pl-4 backdrop-blur-md shadow-lg"
        >
          {/* Custom Dropdown Trigger */}
          <div ref={dropdownRef} className="flex-shrink-0">
            <button
              type="button"
              onClick={() => setIsOpen((prev) => !prev)}
              className="flex items-center gap-2 border-r border-gray-200 dark:border-white/10 pr-3 py-1 cursor-pointer hover:opacity-80 transition-opacity"
            >
              {selected && (
                <div className="relative h-6 w-6 overflow-hidden rounded shadow-sm flex-shrink-0">
                  <Image
                    src={selected.logo ?? getFlagUrl(selected.countryCode)}
                    alt={selected.name}
                    fill
                    className="object-contain"
                  />
                </div>
              )}

              <span className="text-sm font-medium text-gray-600 dark:text-gray-300 whitespace-nowrap">
                {triggerLabel}
              </span>
              <ChevronDown
                className={cn(
                  "w-3.5 h-3.5 text-gray-400 transition-transform duration-200",
                  isOpen && "rotate-180",
                )}
              />
            </button>
          </div>

          {/* Input */}
          <input
            type="text"
            value={number}
            onChange={(e) => {
              const filtered = e.target.value.replace(/\D/g, "");
              setNumber(filtered.slice(0, activeRule.digits));
            }}
            placeholder={activeRule.placeholder}
            maxLength={activeRule.digits}
            className="flex-1 min-w-0 bg-transparent border-none outline-none text-gray-900 dark:text-white text-sm py-2.5 px-2 placeholder:text-gray-400 dark:placeholder:text-gray-500 tracking-widest tabular-nums"
          />

          {/* Search button */}
          <button
            type="submit"
            disabled={loading || !isNumberValid}
            className="flex items-center gap-1.5 bg-gradient-to-r from-gold-500 to-gold-600 hover:from-gold-400 hover:to-gold-500 text-neutral-950 font-bold text-sm py-2.5 px-3 md:px-5 rounded-full shadow-md hover:shadow-lg transition-all disabled:opacity-50 disabled:pointer-events-none flex-shrink-0"
          >
            {loading ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <>
                <Search className="w-4 h-4" />
                <span className="hidden md:inline">{t.common.searchBtn}</span>
              </>
            )}
          </button>
        </form>

        {/* Validation hint */}
        {selected && number.length > 0 && !isNumberValid && (
          <p className="text-xs text-amber-500 dark:text-amber-400 mt-2 text-center" data-testid="validation-hint">
            {t.common.enterNDigits?.replace("{n}", String(activeRule.digits)) ??
              `Enter ${activeRule.description}`}
          </p>
        )}

        {/* Dropdown Panel — full width of form, anchored to outer container */}
        {isOpen && (
          <div ref={panelRef} className="absolute left-0 right-0 mt-2 max-h-[360px] overflow-hidden rounded-xl bg-white dark:bg-neutral-900 border border-gray-200 dark:border-white/10 shadow-2xl z-50 backdrop-blur-xl animate-in fade-in slide-in-from-top-2 duration-200 flex flex-col">
            {/* Search Input */}
            <div className="p-3 border-b border-gray-100 dark:border-white/5 flex-shrink-0">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  ref={searchInputRef}
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.common.searchLotteryPlaceholder}
                  className="w-full bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-white/10 rounded-lg py-2 pl-9 pr-3 text-sm text-gray-900 dark:text-white placeholder:text-gray-400 dark:placeholder:text-gray-500 outline-none focus:ring-2 focus:ring-gold-400/50"
                />
              </div>
            </div>

            {/* Scrollable lottery list */}
            <div className="overflow-y-auto max-h-[280px]">
            {filteredGroups.map((group, gIdx) => (
              <div key={group.countryCode}>
                {/* Country Group Header */}
                {gIdx > 0 && (
                  <div className="h-px bg-gray-100 dark:bg-white/5 mx-3" />
                )}
                <div className="px-4 pt-3 pb-1">
                  <span className="text-fs-badge font-semibold text-gray-500 uppercase tracking-wider">
                    {group.countryName}
                  </span>
                </div>

                {/* Lottery Items */}
                {group.lotteries.map((lottery) => {
                  const isSelected = selected?.id === lottery.id;
                  return (
                    <button
                      key={lottery.id}
                      type="button"
                      onClick={() => handleSelect(lottery)}
                      className={cn(
                        "w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors duration-150",
                        isSelected
                          ? "bg-gold-500/90 text-neutral-950"
                          : "text-gray-900 dark:text-white hover:bg-gray-100 dark:hover:bg-white/10",
                      )}
                    >
                      <div className="relative h-6 w-6 overflow-hidden rounded shadow-sm flex-shrink-0">
                        <Image
                          src={lottery.logo ?? getFlagUrl(lottery.countryCode)}
                          alt={lottery.name}
                          fill
                          className="object-contain"
                        />
                      </div>

                      <span
                        className={cn(
                          "text-sm font-medium truncate",
                          isSelected ? "font-bold" : "",
                        )}
                      >
                        {lottery.name}
                      </span>
                    </button>
                  );
                })}
              </div>
            ))}

            {filteredGroups.length === 0 && (
              <div className="p-4 text-center text-sm text-gray-500">
                {searchQuery ? t.common.noResults : t.common.loading}
              </div>
            )}
            </div>
          </div>
        )}
      </div>

      {/* Results feedback — aria-live for screen reader announcements */}
      {(result || error) && (
        <div className="w-full" aria-live="polite" aria-atomic="true" role="status">
          {error ? (
            <div className="max-w-2xl mx-auto mt-6">
              <div className="p-5 rounded-xl border text-center animate-in fade-in slide-in-from-bottom-4 duration-500 bg-red-500/10 border-red-500/20 text-red-400">
                <div className="flex flex-col items-center gap-2">
                  <XCircle className="w-8 h-8 opacity-80" />
                  <p className="font-bold">{t.common.somethingWrong}</p>
                  <p className="text-sm opacity-80">{error}</p>
                </div>
              </div>
            </div>
          ) : isJackpot ? (
            <JackpotResult result={result!} number={searchedNumber} onReset={handleReset} />
          ) : isWinner ? (
            <StandardWinResult result={result!} number={searchedNumber} onReset={handleReset} />
          ) : (
            <NoWinResult number={searchedNumber} onReset={handleReset} />
          )}
        </div>
      )}
    </section>
  );
}

"use client";

import Link from "next/link";
import Image from "next/image";
import { useLanguage } from "@/contexts/LanguageContext";
import { getFlagUrl } from "@/lib/flags";

export interface CountryListItem {
  id: string;
  name: string;
  count: number;
  flag: string;
}

export function CountryMarqueeSection({
  countries = [],
}: {
  countries?: CountryListItem[];
}) {
  const { t } = useLanguage();

  if (!countries || countries.length === 0) return null;

  // Split countries into two rows
  const midPoint = Math.ceil(countries.length / 2);
  const row1Items = countries.slice(0, midPoint);
  const row2Items = countries.slice(midPoint);

  // We duplicate items exactly once to make the infinite scroll work precisely with the 50% transform
  const row1 = [...row1Items, ...row1Items];
  const row2 = [...row2Items, ...row2Items];

  const Chip = ({ country, index }: { country: CountryListItem; index: number }) => {
    const localizedName =
      t.countryList?.countries?.[
        country.id as keyof typeof t.countryList.countries
      ] || country.name;

    return (
      <Link
        href={`/${country.id}`}
        className="marquee-item group flex items-center gap-4 px-5 py-3.5 rounded-2xl border border-white/10 bg-[#1A1A1A] hover:bg-[#262626] hover:border-gold-500/50 transition-all duration-300 hover:scale-[1.02] shadow-sm flex-shrink-0"
      >
        <div className="relative w-10 h-6 flex-shrink-0 overflow-hidden rounded shadow-sm">
          <Image
            src={getFlagUrl(country.flag)}
            alt={localizedName}
            fill
            className="object-cover"
          />
        </div>
        <div className="flex flex-col min-w-[8rem]">
          <span className="font-bold text-base text-white tracking-wide truncate group-hover:text-gold-400 transition-colors">
            {localizedName}
          </span>
          <span className="text-xs text-gray-400">
            {country.count} {t.countryList?.lotteries || "lottery"}
          </span>
        </div>
      </Link>
    );
  };

  return (
    <section className="bg-transparent py-16 relative z-10 overflow-hidden">
      {/* Title */}
      <div className="text-center mb-10 px-4">
        <h2 className="text-3xl md:text-4xl font-bold text-gray-900 dark:text-white mb-3">
          {t.countryList?.title || "Lottery By Country"}
        </h2>
        <p className="text-sm md:text-base text-gray-500 dark:text-gray-400 max-w-xl mx-auto">
          {t.countryList?.subtitle || "Browse available lotteries by country and explore their latest results."}
        </p>
      </div>

      {/* Marquee Track Container */}
      <div className="country-marquee-container flex flex-col gap-4 relative">
        {/* Left/Right Fading Overlays */}
        <div className="pointer-events-none absolute left-0 top-0 bottom-0 w-16 md:w-32 bg-gradient-to-r from-[var(--background)] to-transparent z-10" />
        <div className="pointer-events-none absolute right-0 top-0 bottom-0 w-16 md:w-32 bg-gradient-to-l from-[var(--background)] to-transparent z-10" />

        {/* Row 1: Scrolling Left */}
        {row1Items.length > 0 && (
          <div className="flex w-max gap-3 animate-marquee-left">
            {row1.map((country, idx) => (
              <Chip key={`row1-${country.id}-${idx}`} country={country} index={idx} />
            ))}
          </div>
        )}

        {/* Row 2: Scrolling Right */}
        {row2Items.length > 0 && (
          <div className="flex w-max gap-3 animate-marquee-right">
            {row2.map((country, idx) => (
              <Chip key={`row2-${country.id}-${idx}`} country={country} index={idx} />
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

"use client";

import { useLanguage } from "@/contexts/LanguageContext";
import { LotteryCardV2 } from "./LotteryCardV2";
import { Compass } from "lucide-react";
import Link from "next/link";
import { HeroItem } from "./HeroSection";

export function HeroSectionV2({ items = [] }: { items?: HeroItem[] }) {
  const { t } = useLanguage();

  // Ensure we have enough items to display a full grid
  // We want at least 12 items to make the columns look full before duplicating.
  const minimumItems = 12;
  const loopCount = Math.max(1, Math.ceil(minimumItems / Math.max(1, items.length)));
  const displayItems = Array(loopCount).fill(items).flat();

  // Split into 4 columns
  const col1 = displayItems.filter((_, i) => i % 4 === 0);
  const col2 = displayItems.filter((_, i) => i % 4 === 1);
  const col3 = displayItems.filter((_, i) => i % 4 === 2);
  const col4 = displayItems.filter((_, i) => i % 4 === 3);

  // Helper for scrolling columns
  const ScrollingColumn = ({ colItems, speedStr, reverse = false, className = "", isHoverable = false }: { colItems: HeroItem[], speedStr: string, reverse?: boolean, className?: string, isHoverable?: boolean }) => {
    // Duplicate the items for seamless infinite scrolling
    const doubleItems = [...colItems, ...colItems];

    return (
      <div className={`relative flex flex-col gap-4 md:gap-6 overflow-hidden ${className}`} style={{ height: "100%", paddingBottom: "24px" }}>
        <div 
          className="flex flex-col gap-4 md:gap-6 w-full scroll-animate"
          style={{
            animation: `${reverse ? "scrollDown" : "scrollUp"} ${speedStr} linear infinite`,
          }}
        >
          {doubleItems.map((item, idx) => (
            <div key={`${item.id}-${idx}`} className="w-full flex-shrink-0">
              <LotteryCardV2 {...item} isHoverable={isHoverable} />
            </div>
          ))}
        </div>
      </div>
    );
  };

  const actionChips = [
    { label: "Trending", href: "?tab=trending#latest-results" },
