"use client";

import React, { useState, useEffect } from "react";
import Confetti from "react-confetti";
import { useWindowSize } from "react-use";
import { Trophy, CheckCircle2, Ticket, AlertCircle, Facebook, Twitter, Link as LinkIcon, RefreshCcw } from "lucide-react";
import { CheckResult } from "./CheckLotteryWidget";
import Link from "next/link";
import { useLanguage } from "@/contexts/LanguageContext";

/**
 * Shared Share Button Component
 */
export const ShareRow = ({ number }: { number: string }) => {
  const { t } = useLanguage();

  // Defer window.location.href to avoid hydration mismatch
  const [currentUrl, setCurrentUrl] = useState("https://lottox.today");
  useEffect(() => {
    setCurrentUrl(window.location.href);
  }, []);

  const shareText = encodeURIComponent(`I checked lottery number ${number} on LOTTOX! 🎉`);
  const shareUrl = encodeURIComponent(currentUrl);

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
    } catch {
      // fallback silently
    }
  };

  return (
    <div className="flex flex-col items-center gap-3 w-full mt-4 pt-4 border-t border-gray-200 dark:border-white/10">
      <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">
        {t.common.shareYourWin}
      </span>
      <div className="flex items-center gap-3">
        <a
          href={`https://www.facebook.com/sharer/sharer.php?u=${shareUrl}&quote=${shareText}`}
          target="_blank"
          rel="noopener noreferrer"
          className="p-2 rounded-full bg-[#1877F2]/10 text-[#1877F2] hover:bg-[#1877F2]/20 transition-colors"
          aria-label="Share on Facebook"
        >
          <Facebook className="w-5 h-5" />
        </a>
        <a
          href={`https://twitter.com/intent/tweet?text=${shareText}&url=${shareUrl}`}
          target="_blank"
          rel="noopener noreferrer"
          className="p-2 rounded-full bg-[#1DA1F2]/10 text-[#1DA1F2] hover:bg-[#1DA1F2]/20 transition-colors"
          aria-label="Share on Twitter"
        >
          <Twitter className="w-5 h-5" />
        </a>
        <button
          onClick={handleCopyLink}
          className="p-2 rounded-full bg-gray-100 dark:bg-white/10 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/20 transition-colors"
          aria-label="Copy link"
        >
          <LinkIcon className="w-5 h-5" />
        </button>
        <a
          href={`https://social-plugins.line.me/lineit/share?url=${shareUrl}`}
          target="_blank"
          rel="noopener noreferrer"
          className="p-2 rounded-full bg-[#06C755]/10 text-[#06C755] hover:bg-[#06C755]/20 transition-colors"
          aria-label={t.common?.shareOnLine ?? "Share on LINE"}
        >
          <svg className="w-5 h-5" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
            <path d="M19.365 9.863c.349 0 .63.285.63.631 0 .345-.281.63-.63.63H17.61v1.125h1.755c.349 0 .63.283.63.63 0 .344-.281.629-.63.629h-2.386c-.345 0-.627-.285-.627-.629V8.108c0-.345.282-.63.627-.63h2.386c.349 0 .63.285.63.63 0 .349-.281.63-.63.63H17.61v1.125h1.755zm-3.855 3.016c0 .27-.174.51-.432.596-.064.021-.133.031-.199.031-.211 0-.391-.09-.51-.25l-2.443-3.317v2.94c0 .344-.279.629-.631.629-.346 0-.626-.285-.626-.629V8.108c0-.271.175-.508.433-.595.06-.023.136-.033.194-.033.195 0 .375.104.495.254l2.462 3.33V8.108c0-.345.282-.63.63-.63.345 0 .63.285.63.63v4.771zm-5.741 0c0 .344-.282.629-.631.629-.345 0-.627-.285-.627-.629V8.108c0-.345.282-.63.627-.63.349 0 .631.285.631.63v4.771zm-2.466.629H4.917c-.345 0-.63-.285-.63-.629V8.108c0-.345.285-.63.63-.63.348 0 .63.285.63.63v4.141h1.756c.348 0 .629.283.629.63 0 .344-.281.629-.629.629M24 10.314C24 4.943 18.615.572 12 .572S0 4.943 0 10.314c0 4.811 4.27 8.842 10.035 9.608.391.082.923.258 1.058.59.12.301.079.766.038 1.08l-.164 1.02c-.045.301-.24 1.186 1.049.645 1.291-.539 6.916-4.078 9.436-6.975C23.176 14.393 24 12.458 24 10.314" />
          </svg>
        </a>
      </div>
    </div>
  );
};

/**
 * 1. Jackpot Result State (1st Prize)
 */
export const JackpotResult = ({
  result,
  number,
  onReset,
}: {
  result: CheckResult;
  number: string;
  onReset: () => void;
}) => {
  const { width, height } = useWindowSize();
  const { t } = useLanguage();

  // Respect prefers-reduced-motion
  const [reducedMotion, setReducedMotion] = useState(false);
  useEffect(() => {
    const mql = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mql.matches);
    const handler = (e: MediaQueryListEvent) => setReducedMotion(e.matches);
    mql.addEventListener("change", handler);
    return () => mql.removeEventListener("change", handler);
  }, []);

  return (
    <div className="relative w-full max-w-2xl mx-auto mt-8 animate-in zoom-in-95 duration-500">
      {/* Full screen confetti — disabled for reduced-motion users */}
      {!reducedMotion && (
        <div className="fixed inset-0 pointer-events-none z-50">
          <Confetti
            width={width}
            height={height}
            recycle={false}
            numberOfPieces={500}
            gravity={0.3}
            colors={["#FFD700", "#F59E0B", "#10B981", "#3B82F6", "#EF4444"]}
          />
        </div>
      )}

      <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-gold-500/20 via-neutral-900 to-neutral-950 border-2 border-gold-500/50 shadow-[0_0_50px_rgba(234,179,8,0.3)] p-6 md:p-8 text-center">
        {/* Glow effect */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-gold-500/20 blur-[100px] -z-10 rounded-full" />

        <div className="flex flex-col items-center gap-4 relative z-10">
          <div className="w-20 h-20 rounded-full bg-gradient-to-tr from-gold-400 to-yellow-200 flex items-center justify-center shadow-lg shadow-gold-500/30 animate-bounce">
            <Trophy className="w-10 h-10 text-neutral-950" />
          </div>

          <h3 className="text-4xl md:text-5xl font-black text-transparent bg-clip-text bg-gradient-to-b from-yellow-200 to-gold-500 uppercase tracking-tight drop-shadow-sm">
            {t.common.jackpotTitle}
          </h3>

          <p className="text-gray-300 text-sm md:text-base mt-2">
            {t.common.numberLabel}{" "}
            <span className="font-bold text-white text-lg px-2 py-1 bg-white/10 rounded mx-1">
              {number}
            </span>{" "}
            {t.common.jackpotMatchedPrize}
          </p>

          {/* Prizes list */}
          {result?.prizes && (
            <div className="w-full max-w-md mt-4 space-y-3">
              {result.prizes.map((p, idx) => (
                <div
                  key={idx}
                  className="flex justify-between items-center bg-neutral-950/80 p-4 rounded-xl border border-gold-500/30 shadow-inner"
                >
                  <span className="text-sm font-medium text-gold-200">
                    {p.prizeName || p.label || t.results.prize1}
                  </span>
                  <span className="font-black text-xl text-gold-400">
                    {p.amount
                      ? `${Number(p.amount).toLocaleString()} ฿`
                      : t.common.jackpotHugePrize}
                  </span>
                </div>
              ))}
            </div>
          )}

          <div className="flex flex-col sm:flex-row gap-3 w-full mt-6">
            <button className="flex-1 py-3 px-6 rounded-full bg-gradient-to-r from-gold-400 to-yellow-400 text-neutral-950 font-bold shadow-lg hover:scale-105 transition-transform">
              {t.common.jackpotHowToClaim}
            </button>
            <button
              onClick={onReset}
              className="flex-1 py-3 px-6 rounded-full bg-white/5 hover:bg-white/10 text-white font-medium border border-white/10 transition-colors"
            >
              {t.common.checkAnothers}
            </button>
          </div>

          <ShareRow number={number} />
        </div>
      </div>
    </div>
  );
};

/**
 * 2. Standard Win Result State (Other Prizes)
 */
export const StandardWinResult = ({
  result,
  number,
  onReset,
}: {
  result: CheckResult;
  number: string;
  onReset: () => void;
}) => {
  const { t } = useLanguage();

  return (
    <div className="relative w-full max-w-2xl mx-auto mt-8 animate-in slide-in-from-bottom-8 duration-500">
      <div className="rounded-2xl bg-white dark:bg-neutral-900 border border-emerald-500/30 shadow-xl overflow-hidden">
        {/* Top green accent bar */}
        <div className="h-2 w-full bg-gradient-to-r from-emerald-400 to-green-500" />

        <div className="p-6 md:p-8 flex flex-col items-center text-center">
          <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-500/20 flex items-center justify-center mb-4">
            <CheckCircle2 className="w-8 h-8 text-emerald-500" />
          </div>

          <h3 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
            {t.common.congratulations}
          </h3>

          <p className="text-gray-600 dark:text-gray-300 text-sm md:text-base">
            {t.common.numberLabel}{" "}
            <span className="font-bold text-gray-900 dark:text-white">{number}</span>{" "}
            {t.common.winnerLabel}
          </p>

          {/* Prizes list */}
          {result?.prizes && (
            <div className="w-full max-w-md mt-6 space-y-2">
              {result.prizes.map((p, idx) => (
                <div
                  key={idx}
                  className="flex justify-between items-center bg-gray-50 dark:bg-neutral-800 p-3 rounded-lg border border-gray-100 dark:border-emerald-500/10"
                >
                  <span className="text-sm font-medium text-gray-600 dark:text-gray-300">
                    {p.prizeName || p.label || t.results.prize1}
                  </span>
                  <span className="font-bold text-emerald-600 dark:text-emerald-400">
                    {p.amount ? `${Number(p.amount).toLocaleString()} ฿` : "-"}
                  </span>
                </div>
              ))}
            </div>
          )}

          <div className="flex flex-col sm:flex-row gap-3 w-full mt-8 max-w-md">
            <button
              onClick={onReset}
              className="flex-1 py-2.5 px-4 rounded-xl bg-gray-100 hover:bg-gray-200 dark:bg-neutral-800 dark:hover:bg-neutral-700 text-gray-900 dark:text-white font-medium transition-colors flex items-center justify-center gap-2"
            >
              <RefreshCcw className="w-4 h-4" />
              {t.common.checkAnotherNumber}
            </button>
            <Link
              href="/global-results"
              className="flex-1 py-2.5 px-4 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white font-medium transition-colors flex items-center justify-center gap-2"
            >
              <Ticket className="w-4 h-4" />
              {t.common.playNextDraw}
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * 3. No Win Result State (Cheer Up & Retention)
 */
export const NoWinResult = ({
  number,
  onReset,
}: {
  number: string;
  onReset: () => void;
}) => {
  const { t } = useLanguage();

  return (
    <div className="relative w-full max-w-2xl mx-auto mt-8 animate-in fade-in duration-300">
      <div className="rounded-2xl bg-white dark:bg-neutral-900 border border-gray-200 dark:border-white/10 shadow-lg p-6 md:p-8 flex flex-col items-center text-center">
        <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-neutral-800 flex items-center justify-center mb-4">
          <Ticket className="w-8 h-8 text-gray-400" />
        </div>

        <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">
          {t.common.notThisTime}
        </h3>

        <p className="text-gray-500 dark:text-gray-400 text-sm md:text-base max-w-md">
          {t.common.numberLabel}{" "}
          <span className="font-bold text-gray-700 dark:text-gray-200">{number}</span>{" "}
          {t.common.noMatchDesc}
        </p>

        {/* Cross-sell / Retention Hook */}
        <div className="w-full bg-blue-50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-500/20 rounded-xl p-4 mt-8 text-center">
          <div className="flex flex-col items-center gap-2">
            <AlertCircle className="w-5 h-5 text-blue-500 flex-shrink-0" />
            <div>
              <h4 className="font-semibold text-blue-900 dark:text-blue-400 text-sm">
                {t.common.upcomingOpp}
              </h4>
              <p className="text-xs text-blue-700 dark:text-blue-300 mt-1 mb-3">
                {t.common.upcomingDesc}
              </p>
              <Link
                href="/global-results"
                className="inline-flex items-center text-xs font-bold text-white bg-blue-500 hover:bg-blue-600 px-4 py-2 rounded-lg transition-colors"
              >
                {t.common.viewUpcoming}
              </Link>
            </div>
          </div>
        </div>

        <button
          onClick={onReset}
          className="mt-6 text-sm font-medium text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-white flex items-center gap-2 transition-colors"
        >
          <RefreshCcw className="w-4 h-4" />
          {t.common.checkAnotherNumber}
        </button>
      </div>
    </div>
  );
};

"use client";

import Link from "next/link";
import Image from "next/image";
import { Globe, Menu, X } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import { ThemeToggle } from "@/components/ui/ThemeToggle";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { usePathname } from "next/navigation";
import { useFeatureToggles } from "@/contexts/FeatureToggleContext";

export function Header() {
  const { t, language, toggleLanguage } = useLanguage();
  const { isFeatureEnabled, toggles } = useFeatureToggles();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const pathname = usePathname();

  const toggleMenu = () => setIsMobileMenuOpen(!isMobileMenuOpen);

  const allNavItems = [
    { label: t.header.home, href: "/", featureKey: "nav_home" },
    { label: t.header.results, href: "/global-results", featureKey: "nav_global_result" },
    { label: t.header.news, href: "/news", featureKey: "nav_articles" },
  ];

  // If a toggle is missing from DB or active=false, we hide the menu item.
  // We check if it is explicitly enabled. 
  // For backwards compatibility or default-on, you could change this check.
  const navItems = allNavItems.filter((item) => {
    // We treat it as enabled if it's either true in DB, 
    // or if the toggle isn't defined at all in DB we can default to true (optional)
    // Here we'll strictly require it to be true if it exists, or fallback to true if not defined.
    if (toggles[item.featureKey] !== undefined) {
      return toggles[item.featureKey] === true;
    }
    return true; // Default to true if not present in DB
  });

  return (
    <header className="sticky top-0 z-50 w-full border-b border-gray-200 dark:border-white/5 bg-white/80 dark:bg-neutral-950/80 backdrop-blur-xl supports-[backdrop-filter]:bg-white/60 dark:supports-[backdrop-filter]:bg-neutral-950/60 transition-colors duration-300 shadow-sm dark:shadow-none">
      <div className="container mx-auto flex h-16 items-center justify-between px-4">
        {/* Logo */}
        <div className="flex items-center gap-2">
          <Link href="/" className="flex items-center gap-2">
            <div className="relative h-10 w-auto overflow-hidden pt-2">
              <Image
                src="/logo-text.png"
                alt="LOTTOX Logo"
                height={100}
                width={100}
                className="object-cover"
              />
            </div>
          </Link>
        </div>

        {/* Desktop Navigation */}
        <nav
          className="hidden md:flex items-center gap-8"
          aria-label="Main navigation"
        >
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={cn(
                "text-sm font-medium transition-colors hover:text-gold-500 dark:hover:text-gold-400",
                pathname === item.href
                  ? "text-gold-600 dark:text-gold-400"
                  : "text-gray-600 dark:text-gray-400",
              )}
            >
              {item.label}
            </Link>
          ))}
        </nav>

        {/* Right Actions */}
        <div className="flex items-center gap-2 sm:gap-4">
          <button
            onClick={toggleLanguage}
            className="flex items-center gap-2 text-sm font-medium text-gray-600 dark:text-gray-300 transition-colors hover:text-black dark:hover:text-white"
            aria-label={`Switch language to ${language === "en" ? "Thai" : "English"}`}
          >
            <Globe className="h-4 w-4" />
            <span>{language.toUpperCase()}</span>
          </button>

          <ThemeToggle />

          {/* Mobile Menu Toggle */}
          <button
            onClick={toggleMenu}
            className="md:hidden p-2 text-gray-600 dark:text-gray-300 hover:text-black dark:hover:text-white"
            aria-label={isMobileMenuOpen ? "Close menu" : "Open menu"}
            aria-expanded={isMobileMenuOpen}
          >
            {isMobileMenuOpen ? (
              <X className="h-6 w-6" />
            ) : (
              <Menu className="h-6 w-6" />
            )}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="border-t border-gray-200 dark:border-white/10 bg-white dark:bg-neutral-900 md:hidden">
          <nav
            className="flex flex-col p-4 space-y-4"
            aria-label="Mobile navigation"
          >
            {navItems.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setIsMobileMenuOpen(false)}
                className={cn(
                  "text-sm font-medium transition-colors hover:text-gold-500 dark:hover:text-gold-400",
                  pathname === item.href
                    ? "text-gold-600 dark:text-gold-400"
                    : "text-gray-600 dark:text-gray-300",
                )}
              >
                {item.label}
              </Link>
            ))}
          </nav>
        </div>
      )}
    </header>
  );
}

"use client";

import { DrawResult } from "./DrawResult";
import { DrawPageHeader } from "./DrawPageHeader";
import { PrizeTierSection } from "./PrizeTierSection";
import { PreviousDrawsSidebar } from "./PreviousDrawsSidebar";
import { FindByNumber } from "./FindByNumber";
import { RecentGlobalDraws } from "./RecentGlobalDraws";
import { NewsSidebar } from "@/components/ui/NewsSidebar";
import { InteractiveTicketVerifier } from "./InteractiveTicketVerifier";
import { NewspaperIcon, ArrowRight, AlertTriangle, Calendar, Award } from "lucide-react";
import { useLanguage } from "@/contexts/LanguageContext";
import Link from "next/link";
import { useApi } from "@/lib/hooks/useApi";
import { ResultsByTypeResponse, ThaiResultData } from "@/lib/api-types";
import { getFlagUrl } from "@/lib/flags";
import Image from "next/image";
import {
  getPrizeNumber,
  getPrizeAmount,
  getPrizeName,
  formatDateDisplay,
  GenericPrizeData,
} from "@/lib/utils/lotteryUtils";

export interface LotteryDetailProps {
  country: string;
  countryCode: string;
  lotteryName: string;
  lotteryId: number;
  lotterySlug: string;
  apiEndpoint: string;
  logo?: string | null;
  currency?: string | null;
  initialData?: ResultsByTypeResponse;
  genericPrizeData?: GenericPrizeData;
  prizeLabels?: {
    firstPrize: string;
    last3f: string;
    last3b: string;
    last2: string;
  };
}

export default function LotteryDetail({
  country,
  countryCode,
  lotteryName,
  lotteryId,
  lotterySlug,
  apiEndpoint,
  logo,
  currency,
  initialData,
  prizeLabels,
}: LotteryDetailProps) {
  const { t, language } = useLanguage();
  const dd = t.staticParams.drawDetail;
  const {
    data: apiData,
    loading,
    error,
  } = useApi<ResultsByTypeResponse>(
    initialData ? null : `${apiEndpoint}?limit=10`,
  );

  const activeData = initialData || apiData;
  const isLoading = !initialData && loading;

  /* ---------- Loading State ---------- */
  if (isLoading) {
    return (
      <div className="container mx-auto px-4 py-8 animate-pulse">
        <div className="mb-8 h-20 rounded-lg bg-slate-100 dark:bg-neutral-800/50" />
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
          <div className="space-y-6 lg:col-span-2">
            <div className="h-96 rounded-2xl bg-slate-100 dark:bg-neutral-800/50" />
            <div className="h-48 rounded-xl bg-slate-100 dark:bg-neutral-800/50" />
            <div className="h-48 rounded-xl bg-slate-100 dark:bg-neutral-800/50" />
          </div>
          <div className="space-y-6">
            <div className="h-48 rounded-xl bg-slate-100 dark:bg-neutral-800/50" />
            <div className="h-48 rounded-xl bg-slate-100 dark:bg-neutral-800/50" />
          </div>
        </div>
      </div>
    );
  }

  /* ---------- Error State ---------- */
  if (error && !initialData) {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="rounded-lg border border-red-500/20 bg-red-500/5 p-8 text-center text-red-500 dark:text-red-400">
          Error loading {lotteryName} results.
        </div>
      </div>
    );
  }

  /* ---------- Data Extraction ---------- */
  const latest = activeData?.latest;
  const historyItems = activeData?.history ?? [];
  const latestData = latest?.data as ThaiResultData | undefined;
  const rawData = latestData as unknown as GenericPrizeData;

  // 1st Prize
  const p1Names = ["Prize 1", "รางวัลที่ 1", "Special Prize", "First Prize", "First Prize (4 Digits)"];
  const p1Cats = ["prize_1", "prizeFirst", "prizeSpecial", "prize_4_digits"];
  const p1Num = getPrizeNumber(rawData, p1Names, p1Cats, 1) || [rawData?.first || rawData?.firstPrize];
  const firstPrize = p1Num && p1Num.length > 0 && p1Num[0] !== undefined ? p1Num[0] : "-";
  const firstPrizeAmount = getPrizeAmount(rawData, p1Names, p1Cats, 1) || rawData?.firstPrizeAmount || "6,000,000";

  // 3-digit front
  const pFront3Names = ["3 Front", "เลขหน้า 3 ตัว", "รางวัลเลขหน้า 3 ตัว"];
  const pFront3Cats = ["running_number_front_3", "prizeLast3Front", "prize_3_front"];
  const front3 = getPrizeNumber(rawData, pFront3Names, pFront3Cats) || rawData?.first3?.number || rawData?.last3f || rawData?.front3 || [];

  // 3-digit back
  const pBack3Names = ["3 Back", "เลขท้าย 3 ตัว", "รางวัลเลขท้าย 3 ตัว", "3 Last Digits"];
  const pBack3Cats = ["running_number_back_3", "prizeLast3Back", "prize_3_back", "prize_3_digits"];
  const back3 = getPrizeNumber(rawData, pBack3Names, pBack3Cats, 2) || rawData?.last3?.number || rawData?.last3b || rawData?.back3 || [];

  // 2-digit last
  const p2Names = ["2 Bottom", "เลขท้าย 2 ตัว", "รางวัลเลขท้าย 2 ตัว", "2 Last Digits"];
  const p2Cats = ["running_number_back_2", "prizeLast2", "prize_2_digits"];
  const l2Num = getPrizeNumber(rawData, p2Names, p2Cats, 3) || rawData?.last2?.number || [rawData?.last2];
  const last2 = Array.isArray(l2Num) ? l2Num[0] : l2Num;

  // Adjacent
  const pAdjNames = ["Adjacent Prizes", "รางวัลข้างเคียงรางวัลที่ 1", "รางวัลข้างเคียง"];
  const pAdjCats = ["nearby_prize_1"];

  // Date
  const rawDateStr = latest?.dateDisplay || latest?.date || "-";
  const formattedDate = formatDateDisplay(rawDateStr, language);

  // Dynamic prizes for non-Thai
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const rawPrizes = (rawData?.prizes || []) as any[];
  const isNonThai = countryCode !== "th";

  /* ---------- Dynamic Prizes for Non-Thai ---------- */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const dynamicHeroPrizes: any[] = [];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const dynamicTierPrizes: any[] = [];

  if (isNonThai && rawPrizes.length > 0) {
    const sorted = [...rawPrizes].sort((a, b) => (a.order ?? 99) - (b.order ?? 99));

    sorted.forEach((p) => {
      const pNumbers = p.winningNumbers || p.number || [];
      const nums = (Array.isArray(pNumbers) ? pNumbers : [pNumbers])
        .map(String)
        .filter((s) => s !== "undefined" && s !== "null" && s !== "");

      const name = (p.prizeName || p.category || "").toLowerCase();
      let isHero = false;

      if (dynamicHeroPrizes.length === 0) {
        isHero = true;
      } else {
        switch(countryCode) {
          case 'la':
            isHero = true;
            break;
          case 'vn':
            if (name.includes("jackpot")) isHero = true;
            break;
          case 'sg':
            if (name.includes("2nd") || name.includes("3rd") || name.includes("additional")) isHero = true;
            break;
          case 'jp':
            if (name.includes("bonus") || name.includes("carry")) isHero = true;
            break;
          case 'au': case 'ca': case 'gb': case 'uk': case 'eu': case 'us':
            if (name.includes("bonus") || name.includes("powerball") || name.includes("mega") || name.includes("lucky") || name.includes("supplementary")) isHero = true;
            break;
          default:
            if (nums.length <= 3 && dynamicHeroPrizes.length < 4 && !name.includes("tier") && !name.includes("division") && !name.includes("group") && !name.includes("consolation") && !name.includes("starter")) {
              isHero = true;
            }
            break;
        }
      }

      if (isHero) {
        dynamicHeroPrizes.push({ ...p, winningNumbers: nums });
      } else {
        dynamicTierPrizes.push({
          title: getPrizeName(p.prizeName || p.category || "Prize", p.category, t),
          count: nums.length,
          amount: String(p.amount || p.prizeAmount || p.reward || p.prize_amount || "0"),
          numbers: nums,
        });
      }
    });
  }

  /* ---------- DrawResult Props ---------- */
  const drawResultProps = {
    country,
    lotteryName,
    date: formattedDate,
    currency: currency || undefined,
    firstPrize: String(firstPrize || "-"),
    firstPrizeAmount: String(firstPrizeAmount),
    dynamicPrizes: isNonThai ? dynamicHeroPrizes : [],
    front3: (Array.isArray(front3) ? front3 : [front3]).map(String).filter((s) => s !== "undefined"),
    front3Amount: String(getPrizeAmount(rawData, pFront3Names, pFront3Cats) || rawData?.first3?.amount || rawData?.front3Amount || "4,000"),
    back3: (Array.isArray(back3) ? back3 : [back3]).map(String).filter((s) => s !== "undefined"),
    back3Amount: String(getPrizeAmount(rawData, pBack3Names, pBack3Cats) || rawData?.last3?.amount || rawData?.back3Amount || "4,000"),
    last2: String(last2 || "-"),
    last2Amount: String(getPrizeAmount(rawData, p2Names, p2Cats) || rawData?.last2?.amount || rawData?.last2Amount || "2,000"),
    adjacent: (getPrizeNumber(rawData, pAdjNames, pAdjCats) || rawData?.adjacent || [])?.map(String),
    adjacentAmount: String(getPrizeAmount(rawData, pAdjNames, pAdjCats) || rawData?.adjacentAmount || "100,000"),
  };

  /* ---------- Prize Tier Data ---------- */
  let prizeTiers: { title: string; count: number; amount: string; numbers: string[] }[] = [];

  if (isNonThai) {
    prizeTiers = dynamicTierPrizes;
  } else {
    prizeTiers = [
      { title: t.results.prize2rank, names: ["Prize 2", "รางวัลที่ 2"], cats: ["prize_2"], fallback: rawData?.prize2, amountFallback: rawData?.prize2Amount || "200,000" },
      { title: t.results.prize3rank, names: ["Prize 3", "รางวัลที่ 3"], cats: ["prize_3"], fallback: rawData?.prize3, amountFallback: rawData?.prize3Amount || "80,000" },
      { title: t.results.prize4rank, names: ["Prize 4", "รางวัลที่ 4"], cats: ["prize_4"], fallback: rawData?.prize4, amountFallback: rawData?.prize4Amount || "40,000" },
      { title: t.results.prize5rank, names: ["Prize 5", "รางวัลที่ 5"], cats: ["prize_5"], fallback: rawData?.prize5, amountFallback: rawData?.prize5Amount || "20,000" },
    ].map((tier) => {
      const numbers = getPrizeNumber(rawData, tier.names, tier.cats) || tier.fallback || [];
      return {
        title: tier.title,
        count: numbers?.length || 0,
        amount: String(getPrizeAmount(rawData, tier.names, tier.cats) || tier.amountFallback),
        numbers: numbers || [],
      };
    });
  }

  /* ---------- All Prizes (for ticket verifier + find-by-number) ---------- */
  const allPrizes: { name: string; amount: string; numbers: string[] }[] = [];
  if (isNonThai && rawPrizes.length > 0) {
    rawPrizes.forEach(
      (p: {
        prizeName?: string; category?: string;
        winningNumbers?: string[]; number?: string | string[];
        amount?: number | string; prizeAmount?: number | string; reward?: number | string;
      }) => {
        const pNumbers = p.winningNumbers || p.number || [];
        const nums = (Array.isArray(pNumbers) ? pNumbers : [pNumbers]).map(String).filter((s: string) => s !== "undefined" && s !== "null");
        allPrizes.push({
          name: getPrizeName(p.prizeName || p.category || "Prize", p.category, t),
          amount: String(p.amount || p.prizeAmount || p.reward || "0"),
          numbers: nums,
        });
      },
    );
  } else {
    if (firstPrize && firstPrize !== "-") allPrizes.push({ name: prizeLabels?.firstPrize || t.results.prize1, amount: drawResultProps.firstPrizeAmount, numbers: [String(firstPrize)] });
    if (front3.length > 0) allPrizes.push({ name: prizeLabels?.last3f || t.results.prize3Front, amount: drawResultProps.front3Amount, numbers: front3.map(String) });
    if (back3.length > 0) allPrizes.push({ name: prizeLabels?.last3b || t.results.prize3Back, amount: drawResultProps.back3Amount, numbers: back3.map(String) });
    if (last2 && last2 !== "-") allPrizes.push({ name: prizeLabels?.last2 || t.results.prize2, amount: drawResultProps.last2Amount, numbers: [String(last2)] });
    if (drawResultProps.adjacent?.length > 0) allPrizes.push({ name: "รางวัลข้างเคียงรางวัลที่ 1", amount: drawResultProps.adjacentAmount, numbers: drawResultProps.adjacent });
    prizeTiers.forEach((p) => {
      if (p.numbers && p.numbers.length > 0) {
        allPrizes.push({ name: p.title, amount: p.amount, numbers: p.numbers.map(String) });
      }
    });
  }

  /* ---------- History data for table ---------- */
  const recentResults = historyItems.map((item) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const d = item.data as any;

    let rFirstPrize = "-";
    let rFront3 = "-";
    let rBack3 = "-";
    let rLast2 = "-";

    if (isNonThai && d.prizes && d.prizes.length > 0) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const sorted = [...d.prizes].sort((a: any, b: any) => (a.order ?? 99) - (b.order ?? 99));
      const p1Nums = sorted[0].winningNumbers || sorted[0].number || [];
      rFirstPrize = (Array.isArray(p1Nums) ? p1Nums.join(" ") : String(p1Nums)) || "-";
    } else {
      const rp1Num = getPrizeNumber(d, p1Names, p1Cats, 1) || [d?.first || d?.firstPrize];
      rFirstPrize = rp1Num && rp1Num.length > 0 && rp1Num[0] !== undefined ? rp1Num[0] : "-";
      const rf3 = getPrizeNumber(d, pFront3Names, pFront3Cats) || d?.first3?.number || d?.last3f || d?.front3 || [];
      rFront3 = String((Array.isArray(rf3) ? rf3 : [rf3])[0] || "-");
      const rb3 = getPrizeNumber(d, pBack3Names, pBack3Cats, 2) || d?.last3?.number || d?.last3b || d?.back3 || [];
      rBack3 = String((Array.isArray(rb3) ? rb3 : [rb3])[0] || "-");
      const rl2Num = getPrizeNumber(d, p2Names, p2Cats, 3) || d?.last2?.number || [d?.last2];
      rLast2 = String(Array.isArray(rl2Num) ? rl2Num[0] : rl2Num) || "-";
      if (rLast2 === "undefined") rLast2 = "-";
    }

    return {
      date: formatDateDisplay(item.dateDisplay || item.date, language),
      firstPrize: rFirstPrize,
      last3f: rFront3,
      last3b: rBack3,
      last2: rLast2,
    };
  });

  /* ==================== RENDER ==================== */
  return (
    <div className="container mx-auto px-4 py-8">
      {/* 1. Header */}
      <DrawPageHeader
        country={country}
        countryCode={countryCode}
        lotteryName={lotteryName}
        lotteryId={lotteryId}
        logo={logo}
      />

      <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
        {/* -------- Main Content (2/3) -------- */}
        <div className="space-y-6 lg:col-span-2">
          {/* 2. Hero — Draw Result */}
          <DrawResult {...drawResultProps} />

          {/* 3. Prize Grids (2nd–5th) */}
          {prizeTiers
            .filter((tier) => tier.numbers.length > 0)
            .map((tier, i) => (
              <PrizeTierSection
                key={i}
                title={tier.title}
                count={tier.count}
                amount={tier.amount}
                currency={currency || t.common.currency}
                numbers={tier.numbers}
                columns={5}
              />
            ))}

          {/* 4. Inline Ticket Verifier */}
          <InteractiveTicketVerifier
            countryCode={countryCode}
            lotterySlug={lotterySlug}
            latestDateDisplay={latest?.dateDisplay || latest?.date || t.common.current}
            historyItems={historyItems}
            prizes={allPrizes}
          />

          {/* 5. Find By Number */}
          <FindByNumber countryCode={countryCode} prizes={allPrizes} />

          {/* 6. Recent Global Draws */}
          <RecentGlobalDraws excludeCountry={countryCode} />

          {/* 7. History Table */}
          <section className="overflow-hidden rounded-2xl border border-slate-200 dark:border-white/10 bg-white dark:bg-neutral-900/80 shadow-sm dark:shadow-none">
            <div className="border-b border-slate-200 dark:border-white/10 px-6 py-4">
              <h3 className="font-bold text-gray-900 dark:text-white">
                {t.results.history}
              </h3>
            </div>

            {/* Desktop Table */}
            <div className="hidden overflow-x-auto lg:block">
              <table className="w-full text-left">
                <thead className="bg-slate-50 dark:bg-white/5 text-[10px] uppercase text-gray-500 dark:text-gray-400">
                  <tr>
                    <th className="px-4 py-3 font-medium">{t.common.date}</th>
                    <th className="px-4 py-3 font-medium">{prizeLabels?.firstPrize || t.results.prize1}</th>
                    {!isNonThai && (
                      <>
                        <th className="px-4 py-3 font-medium">{prizeLabels?.last3f || t.results.prize3Front}</th>
                        <th className="px-4 py-3 font-medium">{prizeLabels?.last3b || t.results.prize3Back}</th>
                        <th className="px-4 py-3 font-medium">{prizeLabels?.last2 || t.results.prize2}</th>
                      </>
                    )}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                  {recentResults.map((row, i) => (
                    <tr
                      key={i}
                      className={`group hover:bg-slate-50 dark:hover:bg-white/5 ${i % 2 === 1 ? "bg-slate-50/50 dark:bg-white/[0.02]" : ""}`}
                    >
                      <td className="px-4 py-4 font-mono text-sm tabular-nums text-gray-600 dark:text-gray-400">{row.date}</td>
                      <td className="px-4 py-4">
                        <div className="font-mono text-xl font-bold tracking-[0.3em] text-gray-900 dark:text-white">{row.firstPrize}</div>
                      </td>
                      {!isNonThai && (
                        <>
                          <td className="px-4 py-4">
                            <span className="rounded border border-blue-500/20 bg-blue-500/10 dark:bg-blue-500/20 px-2 py-0.5 font-mono text-lg font-bold tracking-widest text-blue-600 dark:text-blue-300">{row.last3f}</span>
                          </td>
                          <td className="px-4 py-4">
                            <span className="rounded border border-blue-500/20 bg-blue-500/10 dark:bg-blue-500/20 px-2 py-0.5 font-mono text-lg font-bold tracking-widest text-blue-600 dark:text-blue-300">{row.last3b}</span>
                          </td>
                          <td className="px-4 py-4">
                            <span className="rounded border border-gold-500/20 bg-gold-500/10 dark:bg-gold-500/20 px-2 py-0.5 font-mono text-lg font-bold tracking-widest text-amber-600 dark:text-gold-400">{row.last2}</span>
                          </td>
                        </>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Mobile Card View */}
            <div className="divide-y divide-slate-100 dark:divide-white/5 lg:hidden">
              {recentResults.map((row, i) => (
                <div key={i} className={`space-y-3 px-5 py-4 ${i % 2 === 1 ? "bg-slate-50/50 dark:bg-white/[0.02]" : ""}`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <Image src={getFlagUrl(countryCode)} alt={countryCode} width={24} height={16} className="h-4 w-6 rounded-sm shadow-sm" />
                      <span className="text-sm font-medium text-gray-900 dark:text-white">{lotteryName}</span>
                    </div>
                    <span className="font-mono text-xs text-gray-500">{row.date}</span>
                  </div>
                  <div>
                    <div className="mb-1 text-[10px] uppercase tracking-wider text-gray-500">{prizeLabels?.firstPrize || t.results.prize1}</div>
                    <div className="font-mono text-2xl font-bold tracking-[0.3em] text-gray-900 dark:text-white">{row.firstPrize}</div>
                  </div>
                  {!isNonThai && (
                    <div className="flex flex-wrap items-center gap-3">
                      <div className="flex-1 min-w-[30%]">
                        <div className="mb-1 text-[10px] uppercase tracking-wider text-gray-500">{prizeLabels?.last3f || t.results.prize3Front}</div>
                        <span className="block w-full rounded border border-blue-500/20 bg-blue-500/10 dark:bg-blue-500/20 px-2 py-1 font-mono text-lg font-bold text-blue-600 dark:text-blue-300 text-center">{row.last3f}</span>
                      </div>
                      <div className="flex-1 min-w-[30%]">
                        <div className="mb-1 text-[10px] uppercase tracking-wider text-gray-500">{prizeLabels?.last3b || t.results.prize3Back}</div>
                        <span className="block w-full rounded border border-blue-500/20 bg-blue-500/10 dark:bg-blue-500/20 px-2 py-1 font-mono text-lg font-bold text-blue-600 dark:text-blue-300 text-center">{row.last3b}</span>
                      </div>
                      <div className="flex-1 min-w-[30%]">
                        <div className="mb-1 text-[10px] uppercase tracking-wider text-gray-500">{prizeLabels?.last2 || t.results.prize2}</div>
                        <span className="block w-full rounded border border-gold-500/20 bg-gold-500/10 dark:bg-gold-500/20 px-2 py-1 font-mono text-lg font-bold text-amber-600 dark:text-gold-400 text-center">{row.last2}</span>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </section>

          {/* 8. Disclaimer */}
          <section className="rounded-xl border border-amber-500/20 bg-amber-500/5 p-5">
            <div className="flex items-start gap-3">
              <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-amber-500 dark:text-amber-400" />
              <p className="text-sm leading-relaxed text-gray-600 dark:text-gray-300">
                {dd.disclaimer}
              </p>
            </div>
          </section>
        </div>

        {/* -------- Sidebar (1/3) -------- */}
        <aside className="space-y-6">
          {/* Sidebar Ticket Verifier */}
          <InteractiveTicketVerifier
            variant="sidebar"
            countryCode={countryCode}
            lotterySlug={lotterySlug}
            latestDateDisplay={latest?.dateDisplay || latest?.date || t.common.current}
            historyItems={historyItems}
            prizes={allPrizes}
          />

          {/* Previous Draws */}
          <PreviousDrawsSidebar
            countryCode={countryCode}
            lotterySlug={lotterySlug}
            historyItems={historyItems}
          />

          {/* News Sidebar */}
          <NewsSidebar
            accentColor="gold"
            icon={<NewspaperIcon className="h-4 w-4 text-amber-600 dark:text-gold-400" />}
            category={countryCode}
          />
        </aside>
      </div>
    </div>
  );
}

